import {primaryProjects} from './course-ages.js';
import {guides} from './guides.js';
import {subjects} from './curriculum.js';
// Authored topic extensions. Each question includes a numeric target and a worked rationale.
// Presentation is age-adapted; challenge level is a separate learner choice/evidence signal.
const q=(prompt,answer,reason)=>({prompt,answer,reason});
export const extensions={
math:[
{prereq:'Count to twenty and group equal objects.',why:'Place value lets a small set of symbols describe large measurements and prices.',depth:'In a positional system, a digit contributes digit × base^position. Carrying is exchanging ten units at one place for one at the next. Subtraction reverses that exchange. A zero preserves an empty place: 205 is not 25. This representation extends to decimal places using negative powers of ten.',advanced:'For base b≥2, N=Σdᵢbⁱ with 0≤dᵢ<b. Uniqueness follows by comparing residues modulo b, then dividing by b recursively. Finite precision can overflow even when the mathematical integer is well-defined.',example:'Subtract 52−18: exchange one ten for ten ones, so 52 is four tens and twelve ones. Twelve minus eight is four; four tens minus one ten is three tens. Result: 34. Check 34+18=52.',mistake:'Regrouping does not add value. One hundred equals ten tens, not ten extra hundreds.',model:'place',questions:[q('Two tens and three ones make what number?',23,'2×10+3=23.'),q('In 407, what value does the digit 4 represent?',400,'The 4 is in the hundreds place: 4×100=400.'),q('Write 52 in base eight. Enter the digits as a number.',64,'52=6×8+4, so its base-eight digits are 64.')],rubric:'Show a decomposition, a regrouping, and an addition check.'},
{prereq:'Recognize equal parts and count groups.',why:'Recipes, maps, and comparisons rely on preserving ratios.',depth:'To compare fractions, describe them using equal-sized units. A common denominator gives a shared unit: 1/2=3/6 and 1/3=2/6, so 1/2+1/3=5/6. For multiplication, taking a fraction of a fraction multiplies numerators and denominators. Division asks how many copies of one amount fit inside another.',advanced:'Rational numbers are equivalence classes of integer pairs (a,b), b≠0, where (a,b)~(c,d) iff ad=bc. Operations must be invariant under representative changes. Exact rational arithmetic avoids some floating-point equality problems.',example:'To share 3/4 litre using 1/8-litre cups, compute (3/4)÷(1/8)=6. Six cups each containing 1/8 litre total 6/8=3/4 litre.',mistake:'Adding denominators changes the unit incorrectly. 1/2+1/2 is one whole, not 2/4.',model:'fraction',questions:[q('How many of four equal pieces make half?',2,'Two equal fourths cover half.'),q('How many eighths equal three quarters?',6,'Multiply numerator and denominator by 2: 3/4=6/8.'),q('For 1/2 + 1/3 = n/6, find n.',5,'A common denominator gives 3/6+2/6=5/6.')],rubric:'Use equal wholes, show a common unit, and verify the result by reconstruction.'},
{prereq:'Use inverse addition and subtraction.',why:'An equation finds an unknown while keeping a relationship true.',depth:'Expressions name quantities; equations claim equality. Terms are separated by addition or subtraction. In 3x+2, 3 is a coefficient and 2 a constant. Undo operations in reverse order while doing the same thing to both sides. Substitution checks whether a proposed value satisfies the original equation.',advanced:'An affine equation ax+b=c has one solution when a≠0. If a=0 it has either all real solutions (b=c) or none (b≠c). Multiplying by an expression that may be zero or squaring both sides can change the solution set, so check domain restrictions.',example:'Solve 3(x−2)=12. Divide both sides by 3: x−2=4. Add 2: x=6. Substitution gives 3(6−2)=12. Alternatively expand to 3x−6=12, then isolate x.',mistake:'A term cannot simply “move” across an equals sign without an inverse operation on both sides.',model:'equation',questions:[q('A mystery bag and 3 blocks make 8 blocks. How many are in the bag?',5,'Subtract 3 from both sides: 8−3=5.'),q('Solve 2x+3=11. What is x?',4,'Subtract 3, then divide by 2.'),q('Solve 3(x−2)=12. What is x?',6,'Divide by 3, then add 2; substitution verifies 6.')],rubric:'Name each reversible operation and verify by substitution.'},
{prereq:'Count unit squares and measure lengths.',why:'Area estimates material; perimeter estimates edging or fencing.',depth:'A rectangular array has one row of unit squares per width unit and one square per length unit. Multiplying counts the array. A triangle is half a parallelogram with the same base and perpendicular height. Similar shapes scale lengths by k but areas by k²; surface and volume scaling differ.',advanced:'Area is additive over non-overlapping regions and scales quadratically under uniform similarity. For a fixed rectangular perimeter P, A=x(P/2−x) is maximized at x=P/4; a square maximizes area among rectangles with that perimeter.',example:'A triangle with base 8 cm and perpendicular height 3 cm has area (8×3)/2=12 cm². Its sloping side is not its height unless perpendicular to the base.',mistake:'A height must be perpendicular. A perimeter measured in cm cannot be compared directly with area in cm².',model:'area',questions:[q('A floor has 3 rows of 4 square tiles. How many tiles?',12,'Three groups of four give 12.'),q('What is the perimeter of a 5 by 3 rectangle?',16,'Add 5+3+5+3=16 length units.'),q('A rectangle has perimeter 20. What is the largest possible area?',25,'The maximizing rectangle is a 5×5 square, with area 25.')],rubric:'Include a labeled diagram, correct units, and an independent count or formula check.'},
{prereq:'Substitute numbers in a simple expression.',why:'Functions connect changing inputs to predictable outputs.',depth:'A table lists sample input-output pairs; a graph represents all allowed pairs. An intercept is the output when the input is zero. A constant slope describes a linear rate, while a quadratic rate changes. A relationship may have a restricted domain: negative ticket counts are not meaningful.',advanced:'For f(x)=mx+b, Δf/Δx=m for nonzero Δx. Composition applies one mapping after another; inverse functions require injectivity on the chosen domain. A finite sample can fit several models, so model selection needs assumptions and out-of-sample evidence.',example:'A taxi charges 4 units plus 2 per kilometre: f(x)=2x+4. At x=3, cost is 10. At x=5, cost is 14. The 4-unit increase over 2 km confirms the slope of 2.',mistake:'The graph’s height is output, not slope. A high horizontal line has zero slope.',model:'function',questions:[q('A machine doubles 3 and adds 1. What comes out?',7,'2×3+1=7.'),q('For f(x)=3x−2, find f(4).',10,'3×4−2=10.'),q('If f(x)=2x+1 and g(x)=x², what is g(f(3))?',49,'First f(3)=7, then g(7)=49.')],rubric:'State a domain, make a table, and test the proposed rule on a new input.'},
{prereq:'Count equally likely outcomes and compare fractions.',why:'Probability supports decisions when individual results are uncertain.',depth:'An outcome is one possible result; an event is a set of outcomes. Complementary probabilities sum to one. For independent events, multiply probabilities, but independence must be justified. Empirical frequency estimates a probability and varies from trial to trial.',advanced:'Conditional probability P(A|B)=P(A∩B)/P(B) for P(B)>0 changes the reference set. Independence means P(A∩B)=P(A)P(B), not mutual exclusivity. An estimator’s uncertainty depends on sample size and collection design.',example:'Two fair independent coin flips yield HH, HT, TH, TT. Exactly one head occurs in two of four outcomes, probability 1/2. At least one head occurs in three, probability 3/4.',mistake:'A streak of tails does not make the next independent fair flip “owe” a head.',model:'probability',questions:[q('A fair coin has heads and tails. How many possible sides can land upward?',2,'There are two modeled outcomes.'),q('Out of four equally likely two-coin outcomes, how many have at least one head?',3,'HH, HT, and TH each have a head.'),q('A fair die is known to show an even number. What percent chance is it a 6? Round to two decimals.',33.33,'Condition on {2,4,6}; one of three is 6, about 33.33%.')],rubric:'List the outcome space, state independence assumptions, and distinguish predictions from observed frequencies.'}
],
science:[
{prereq:'Distinguish objects, materials, and changes of state.',why:'Particle models explain familiar changes without seeing each particle.',depth:'Atoms are chemical building blocks; molecules contain bonded atoms. Particle diagrams are models, not scaled photographs. In a closed container, changing physical state conserves the amount of material. Temperature tracks average thermal motion, while energy can also change arrangements and bonds.',advanced:'A phase model depends on pressure and composition. At equilibrium for a pure substance, latent heat changes phase at a fixed transition temperature at fixed pressure. Water’s familiar 0 °C and 100 °C boundaries are approximate at standard atmospheric pressure; nucleation and impurities matter.',example:'If 20 g of ice melts inside a sealed container without leaks, the resulting water still has mass 20 g. Its shape and density may change, but no material has left the system.',mistake:'Heating does not make individual atoms expand into large visible pieces. Changes in spacing and arrangement matter.',model:'particles',questions:[q('A sealed box has 6 ice pieces. If none leave, how many pieces’ worth of water remains after melting?',6,'The material stays in the sealed box.'),q('Twenty grams of sealed ice melts. What mass of water remains in grams?',20,'Mass is conserved in this physical change.'),q('Melting 2 kg of ice needs 334 kJ/kg. How much energy is needed in kJ at the melting point?',668,'Q=mL=2×334=668 kJ; temperature stays fixed during ideal melting.')],rubric:'Label model assumptions, show particle arrangement, and account for conserved material.'},
{prereq:'Read arrows with size and direction.',why:'Net force explains how motion changes rather than merely describing movement.',depth:'Choose a positive direction and add signed force components. Equal opposite forces on the same object cancel in the net force. Newton’s third-law partners act on different objects and do not cancel on one free-body diagram. Acceleration depends on net force and mass.',advanced:'ΣF=ma applies in an inertial frame for constant mass. Forces and accelerations are vectors. A free-body diagram defines the system boundary; internal forces cancel when summing over a whole system, whereas external forces determine center-of-mass acceleration.',example:'A 2 kg trolley feels 10 N right and 4 N left. Net force is +6 N, so acceleration is +3 m/s². If already moving left, it initially slows rather than instantly moving right.',mistake:'Zero net force allows constant nonzero velocity. Motion alone is not evidence of a net force.',model:'force',questions:[q('One friend pulls with 5 and another pulls oppositely with 2. How much pull is left toward the stronger friend?',3,'5−2=3.'),q('A 2 kg cart has net force 6 N. What is acceleration in m/s²?',3,'a=F/m=6/2=3.'),q('A 3 kg cart feels 15 N right and 6 N left. From rest, what speed follows after 4 s in m/s?',12,'Net force 9 N gives a=3; v=at=12 m/s.')],rubric:'Draw forces on one object, choose signs, and check units and initial conditions.'},
{prereq:'Compare quantities and identify an input and output.',why:'Tracking energy reveals costs, useful outputs, and environmental transfers.',depth:'Define a system before accounting for energy. Energy is transferred across its boundary or stored within it. Heating is energy transfer caused by temperature difference; temperature is not a quantity of energy. Power is the rate of energy transfer, measured in watts = joules per second.',advanced:'A steady energy balance has input power equal to useful output plus other transfers. Efficiency η=Puseful/Pin is dimensionless. Entropy and irreversibility constrain conversion of heat to work; energy conservation alone does not imply every conversion is equally feasible.',example:'A motor takes 200 J over 4 s and delivers 150 J mechanically. Input power is 50 W, useful power 37.5 W, and efficiency is 75%. The remaining 50 J transfers elsewhere.',mistake:'“Wasted” energy is not destroyed; it becomes less useful for the intended task.',model:'energy',questions:[q('Ten energy tokens go in. Six help move a toy. How many go to other changes?',4,'10−6=4.'),q('A device gets 100 J and uses 60 J usefully. What is its efficiency in percent?',60,'60/100×100=60%.'),q('A motor receives 200 J in 4 s. What is input power in watts?',50,'Power=energy/time=200/4=50 W.')],rubric:'Define the system, balance the energy, and distinguish power from energy.'},
{prereq:'Identify living things and parts with different functions.',why:'Cell structure connects small-scale processes to the functioning of organisms.',depth:'Membranes separate internal conditions from the environment while permitting controlled exchange. Cells need resources and remove wastes. Specialized cells form tissues with coordinated jobs. Genetic information influences proteins and functions, but environment also affects outcomes. Cell division is regulated, not unlimited doubling.',advanced:'Surface area scales with characteristic length squared and volume cubed. This changes exchange demands as cells grow. Exponential doubling is a deliberately simplified model over limited conditions; resource limitations, death, and regulation invalidate indefinite extrapolation.',example:'An ideal population starting with 3 cells doubles twice: 3→6→12. Four doublings give 48. This is an arithmetic growth model, not a universal biological growth rate.',mistake:'Not every cell has a nucleus or chloroplasts. Bacterial cells lack a membrane-bound nucleus.',model:'cells',questions:[q('Two cells each split into two in a model. How many are there now?',4,'Each of the two produces two: four total.'),q('A model starts with 3 cells and doubles twice. How many?',12,'3×2×2=12.'),q('A cube-shaped cell doubles every length. By what factor does volume grow?',8,'Volume scales as length cubed: 2³=8.')],rubric:'Connect structure with function and state where a growth model stops being realistic.'},
{prereq:'Understand a complete circuit and use division.',why:'Voltage, current, and resistance help predict safe low-voltage circuit behavior.',depth:'Voltage describes energy transferred per unit charge, current describes charge per time, and resistance relates voltage to current under stated conditions. In series the same current crosses each component; in parallel branches share voltage. Charge is conserved at junctions.',advanced:'Ohm’s law is a constitutive relationship for ohmic materials over appropriate temperature ranges, not a universal law for every device. Power is P=VI, and for an ohmic resistor also I²R or V²/R. Source internal resistance and component ratings affect real circuits.',example:'A 9 V ideal source and 3 Ω resistor give I=3 A. Power is 9×3=27 W; that is large for many small resistors, so the arithmetic does not establish physical safety.',mistake:'Current is not “used up” by a resistor. Energy transfers while charge continues around the circuit.',model:'ohm',questions:[q('A circuit has one gap. How many gaps must be closed to make one complete path?',1,'The one break prevents a complete loop.'),q('An ideal 6 V source across 3 Ω gives how many amperes?',2,'I=V/R=6/3=2 A.'),q('A 12 V source drives a 6 Ω resistor. What is power in watts?',24,'I=2 A, then P=VI=12×2=24 W.')],rubric:'Use a virtual or low-voltage model, track units, and check component limits before any physical build.'},
{prereq:'Recognize a rotation and a yearly orbit.',why:'Geometry of sunlight explains cycles observed across locations and seasons.',depth:'Earth’s daily rotation exposes different longitudes to sunlight. The yearly orbit changes which hemisphere tilts toward the Sun. Greater solar elevation concentrates energy over a smaller ground area, and longer days extend exposure. Moon phases arise from viewing its sunlit half, not usually Earth’s shadow.',advanced:'Solar declination and latitude determine solar elevation and daylight duration. The simple 24-hour/360-degree rotation model estimates longitude time differences but omits time-zone policy and the distinction between solar and sidereal days. Seasonal climate also depends on thermal inertia and circulation.',example:'In the simple daily rotation model, Earth rotates 360° in 24 hours, or 15° per hour. Two longitudes 30° apart differ by about two hours of local solar time, not necessarily clock time.',mistake:'Seasons are not caused mainly by Earth being nearer the Sun; opposite hemispheres experience opposite seasons.',model:'earth',questions:[q('One full day and night takes about how many hours?',24,'The simplified solar-day cycle lasts about 24 hours.'),q('At 15 degrees per hour, how many degrees rotate in 2 hours?',30,'15×2=30°.'),q('Two longitudes differ by 75°. Estimate their local solar time difference in hours.',5,'75/15=5 hours; legal time zones may differ.')],rubric:'Use a tilted model, distinguish rotation from orbit, and separate model time from clock conventions.'}
],
coding:[
{prereq:'Follow steps in a specified order.',why:'Decomposition turns a vague goal into steps that can be tested.',depth:'Specify inputs, outputs, and valid cases before writing syntax. Break the task into subproblems with contracts. Trace a small input by hand to check ordering and state changes. An algorithm can be expressed in words, flowcharts, or several programming languages.',advanced:'A specification defines correctness; an implementation is one way to satisfy it. Loop invariants or induction can establish correctness beyond examples. Complexity describes resource growth with input size, while constant costs still matter in practice.',example:'To find max(3,8,5), initialize best=3. Compare 8 and replace best. Compare 5 and keep best=8. Starting best at zero would fail if all values were negative.',mistake:'A list of vague intentions is not executable until each step and decision is precise.',model:'maximum',questions:[q('Pip compares 2, 5, and 3 blocks. What is the biggest pile?',5,'Compare all three; five is largest.'),q('What should a maximum algorithm return for −4, −2, −8?',-2,'−2 is greater than −4 and −8; do not initialize to zero.'),q('A sequential maximum scan of 10 items needs how many pairwise comparisons?',9,'Use the first as the initial best and compare the other nine.')],rubric:'State the contract, trace a normal input, and test a boundary or adversarial input.'},
{prereq:'Distinguish a name from the object it names.',why:'Variables let programs remember and transform information.',depth:'An assignment evaluates the right side before storing its result in the binding on the left. Types determine available operations. JavaScript numbers use floating-point representation; strings concatenate with +. const prevents reassignment of a binding but does not automatically freeze an object.',advanced:'IEEE-754 arithmetic approximates many real numbers. Aliasing means two bindings can refer to the same mutable object, unlike independent scalar values. Type conversion rules and mutation boundaries should be explicit to avoid hidden behavior.',example:'let x=4; let y=x; x=7; leaves y=4 because the numeric value was copied. With objects, two variables can instead refer to the same object and observe its mutations.',mistake:'The assignment x=x+1 is not a mathematical equality; it updates a stored value after evaluating the old one.',model:'variable',questions:[q('The score is 2. Add 3. What is the new score?',5,'Use the old score 2, then add 3.'),q('let x=4; let y=x; x=7; What numeric value is y?',4,'Assigning a primitive number copies its value.'),q('let x=3; x=x*2; x=x+4; What is x?',10,'First x becomes 6, then 10.')],rubric:'Trace each assignment and explicitly distinguish numbers, strings, and shared references.'},
{prereq:'Compare two values and understand true/false.',why:'Conditions let a program respond differently to different inputs.',depth:'A branch evaluates its condition at runtime, then executes the selected body. Nested branches can express multiple rules, but ordering matters. Boolean AND requires both operands to be true; OR needs at least one. Boundary tests reveal mistakes in < versus <=.',advanced:'A decision table enumerates combinations and makes overlap or missing cases visible. Short-circuit evaluation can prevent invalid accesses, but side effects inside conditions complicate reasoning. Input validation must precede decisions that assume well-formed data.',example:'A child-ticket rule age<10 includes 9 but excludes 10. A rule age<=10 includes both. Test 9, 10, and 11 to distinguish the intended policy.',mistake:'Writing = in a condition can assign rather than compare. In JavaScript, === checks strict equality.',model:'condition',questions:[q('If 4 is less than 5, enter 1 for true or 0 for false.',1,'Four is less than five, so the condition is true.'),q('For age<10, does age 10 qualify? Enter 1 for yes, 0 for no.',0,'The boundary 10 is excluded by <.'),q('For (x>2 && x<6), how many integer values satisfy the condition?',3,'The values 3,4,5 satisfy both comparisons.')],rubric:'Write a decision table and test both sides of each boundary.'},
{prereq:'Trace assignments and evaluate a condition.',why:'Loops express repetition without duplicating instructions.',depth:'A for loop initializes state, checks a condition, runs the body, and updates state. A while loop exposes the same logic but may place updates inside its body. Choose a finite bound or a decreasing measure to guarantee termination. Trace before executing.',advanced:'For a running sum, the invariant states that the accumulator equals the sum of processed items. A nonnegative variant that decreases each iteration proves termination. Nested loops may be quadratic, but exact bounds determine their complexity.',example:'let total=0; for(let i=1;i<=4;i++){total+=i;} visits 1,2,3,4 and produces 10. If the condition were i<4, the total would be 6.',mistake:'A loop condition is checked before a for/while body, so the loop may run zero times.',model:'loop',questions:[q('Repeat “step” three times. How many steps happen?',3,'One action per repeat gives three steps.'),q('for(let i=0;i<5;i++) runs how many times?',5,'Counter values 0,1,2,3,4 give five iterations.'),q('What is the total after adding integers 1 through 4?',10,'1+2+3+4=10; the inclusive endpoint matters.')],rubric:'Identify initialization, condition, update, output, and a reason the loop terminates.'},
{prereq:'Evaluate expressions and identify inputs/outputs.',why:'Functions isolate reusable behavior and make testing smaller.',depth:'Parameters are local names for arguments supplied at a call. A return statement sends a value back and ends that invocation. Scope determines where bindings are accessible. Pure functions depend only on inputs and avoid external mutation, which simplifies tests.',advanced:'Function contracts state preconditions and postconditions. Closures capture lexical bindings, not always frozen values. Referential transparency enables equational reasoning; practical programs isolate side effects at clear boundaries.',example:'function area(w,h){return w*h;} returns 12 for area(3,4). Calling console.log inside a function displays output but does not return that displayed value to the caller.',mistake:'Printing a result and returning it are different operations. A function without an explicit JavaScript return yields undefined.',model:'function',questions:[q('A doubling machine takes 4. What comes back?',8,'4×2=8.'),q('area(3,4) returns width times height. What is returned?',12,'The parameter values multiply to 12.'),q('If f(x)=2x+1, what is f(f(2))?',11,'f(2)=5, then f(5)=11.')],rubric:'Specify inputs and result, test boundary values, and separate returned values from side effects.'},
{prereq:'Read loops, arrays, and comparisons.',why:'Testing and analysis reveal when an apparently working algorithm fails.',depth:'A linear search examines items in order until a match or the end. Binary search requires sorted data and repeatedly halves a candidate interval. Tests should cover empty inputs, duplicates, absent targets, and boundaries. Debugging compares expected state with observed state to locate the first divergence.',advanced:'Worst-case bounds are not the same as average behavior. Binary search has logarithmic comparisons under random-access sorted data, while sorting and maintaining that data have costs. A test suite samples behavior; proofs and invariants can establish broader guarantees.',example:'Search [4,7,9] for 7: compare 4, then 7; return index 1. Search for 3: three comparisons find no match. An absent-item result should be explicit, such as −1.',mistake:'Binary search on unsorted input is not reliable, even if a few examples happen to work.',model:'search',questions:[q('Pip checks cards 4,7,9 in order for 7. How many cards are checked?',2,'Check 4 first, then find 7.'),q('A linear search misses in a 6-item list. How many items must it examine?',6,'Every item must be ruled out.'),q('How many halvings reduce 32 candidates to 1?',5,'32→16→8→4→2→1 is five halvings.')],rubric:'Include empty, absent, duplicate, and boundary tests, and justify the algorithm’s assumptions.'}
],
cs:[
{prereq:'Understand place value and on/off states.',why:'Shared encodings let physical circuits represent numbers and symbols.',depth:'A bit has two modeled states. An unsigned n-bit word represents integers 0 through 2ⁿ−1. Text requires an encoding such as UTF-8; bits do not inherently mean letters. A processor follows encoded instructions and uses registers, memory, and input/output systems.',advanced:'Representation and interpretation must be distinguished: the same bit pattern can denote an integer, instruction, or encoded byte. Signed representations such as two’s complement change the range. Endianness specifies byte order, not the meaning of each bit.',example:'Binary 1101₂ equals 8+4+0+1=13. Four bits represent 16 distinct patterns. Adding 1 to unsigned 1111 overflows a four-bit result unless a carry is stored elsewhere.',mistake:'A byte is eight bits, not eight decimal digits; encoding determines what the bits mean.',model:'binary',questions:[q('Switches worth 4 and 2 are on. What value do they make?',6,'Add the active weights: 4+2=6.'),q('What decimal value is binary 1011?',11,'8+0+2+1=11.'),q('What is the largest unsigned integer stored in 8 bits?',255,'There are 256 patterns, numbered 0 through 255.')],rubric:'Show place weights, state the encoding, and test a boundary value.'},
{prereq:'Distinguish stored data from running instructions.',why:'Operating systems share finite hardware among independent programs.',depth:'A process has execution state and an address space; threads within a process share much of that space. The OS schedules execution and maps virtual memory. Isolation is enforced by hardware and software permissions, not by simply assigning different variable names.',advanced:'Virtual memory separates logical addressing from physical placement. Paging introduces faults and replacement policies. Concurrency requires synchronization because interleavings can violate assumptions. The simplified capacity model below omits caches, kernel reservations, and virtual-memory overcommit.',example:'With 16 units of modeled RAM, processes using 5 and 7 units leave 4 free. A new 6-unit allocation cannot fit without freeing or moving data in this simplified physical-capacity model.',mistake:'Closing a window does not always mean its background process has stopped.',model:'memory',questions:[q('A shelf has 8 spaces. Three are used. How many remain?',5,'8−3=5 free spaces.'),q('A 16-unit memory model uses 5 and 7 units. How many remain?',4,'16−5−7=4.'),q('Four 4 KiB pages use how many bytes?',16384,'4×4×1024=16384 bytes.')],rubric:'Draw a resource map, distinguish virtual and physical memory, and explain one isolation guarantee.'},
{prereq:'Trace a message through connected nodes.',why:'Layered protocols let independent networks exchange useful information.',depth:'DNS maps names to addresses. IP routes packets between networks. A transport protocol manages endpoint communication; TCP adds reliable ordered delivery, while UDP does not by itself. HTTP specifies application requests and responses. TLS protects transport confidentiality and integrity when correctly authenticated.',advanced:'Latency, throughput, and reliability are different metrics. Store-and-forward delay includes L/R for packet size L and link rate R, plus propagation, processing, and queues. Encryption does not guarantee the application content is true or benign.',example:'A request traverses links taking 2,3,4 ms, for a one-way delay of 9 ms. If a response returns on identical delays with no processing wait, round-trip time is 18 ms.',mistake:'Fewest hops need not mean lowest latency; link rates and congestion matter.',model:'network',questions:[q('A parcel travels over 3 links. How many links does it cross?',3,'Count each connection in the route.'),q('Links take 2,3,4 ms. What is total one-way delay?',9,'Add the three delays: 2+3+4=9 ms.'),q('A 12,000-bit packet crosses two 1 Mbit/s store-and-forward links. Ignoring other delay, how many milliseconds?',24,'Each needs 12000/1000000 s=12 ms; two links need 24 ms.')],rubric:'Label each protocol’s role and separate transmission delay, propagation, and queueing assumptions.'},
{prereq:'Read rows and columns and recognize unique identifiers.',why:'Structured data supports reliable lookup, updates, and relationships.',depth:'A primary key identifies a row. A foreign key refers to a valid row in another table. Normalization reduces duplicated facts and update anomalies. Queries should use parameterized values rather than concatenate untrusted input. Transactions group operations that must succeed or fail together.',advanced:'Relational constraints encode invariants, while isolation levels govern concurrent transactions. An atomic revision check prevents lost updates. Indexes can accelerate reads at the cost of storage and write work; query performance depends on selectivity and plans.',example:'Books(id,title) and Loans(id,book_id,learner_id) record multiple borrowing events without duplicating the book title in every event. A foreign key rejects a loan referencing a nonexistent book.',mistake:'A display name is not necessarily unique or stable enough to serve as a primary key.',model:'database',questions:[q('Three books have different ID numbers. How many unique IDs are needed?',3,'Each book needs one distinct identifier.'),q('Rows have scores 2,5,8. How many satisfy score>=5?',2,'The rows with 5 and 8 satisfy the condition.'),q('Two devices read revision 7. The first saves revision 8. How many of the two writes should succeed with an expected revision of 7?',1,'Only the first compare-and-swap matches revision 7; the other must reload and merge.')],rubric:'Choose keys, define a relationship, and demonstrate one rejected invalid or conflicting write.'},
{prereq:'Distinguish identity from permission.',why:'Security protects confidentiality, integrity, and availability of data.',depth:'Authentication checks who is requesting access; authorization checks what they may do. Least privilege limits permissions. Passwords should be handled by a trusted authentication service using appropriate password hashing, not stored in plaintext. Client-side hiding is not an authorization boundary.',advanced:'Threat models identify assets, actors, trust boundaries, and plausible failures. Defense in depth combines input validation, session controls, access policies, and monitoring. Encryption protects specific channels or storage but does not repair flawed authorization logic.',example:'Learner A requests learner B’s progress. The server verifies A’s identity, then an ownership policy rejects the read because A’s user ID does not equal the record owner. A valid login alone is insufficient.',mistake:'A signed-in user is not automatically authorized to access every record.',model:'permission',questions:[q('A key opens your own locker. Should it open a friend’s locker? Enter 1 for yes, 0 for no.',0,'Permission belongs to the intended owner.'),q('A user is logged in but does not own a private record. Allow access? Enter 1 for yes, 0 for no.',0,'Authentication does not replace authorization.'),q('A role needs read and write but not delete. How many of those three permissions should it receive?',2,'Least privilege grants the two required permissions only.')],rubric:'Identify an asset and trust boundary, then test an unauthorized request at the server boundary.'},
{prereq:'Understand labeled examples and compare predictions with outcomes.',why:'Evaluation helps distinguish useful learned patterns from misleading shortcuts.',depth:'Training adjusts a model using examples; testing estimates performance on separate data. Labels and sampling choices define what can be learned. Accuracy can hide uneven class performance. A model’s confident output is not proof, and deployment conditions may differ from training conditions.',advanced:'Precision=TP/(TP+FP) and recall=TP/(TP+FN) measure different errors. Threshold selection trades them off. Leakage inflates evaluation, and distribution shift breaks representativeness. A causal claim requires stronger identification than predictive association.',example:'A classifier makes 8 correct predictions out of 10, accuracy 80%. If nine examples belong to one class, always predicting that class reaches 90% without recognizing the other class at all.',mistake:'Reusing training examples as a test can overestimate generalization.',model:'accuracy',questions:[q('A model gets 3 of 4 pictures right. How many are wrong?',1,'4−3=1 mistake.'),q('Eight correct predictions out of ten give what accuracy percentage?',80,'8/10×100=80%.'),q('A detector has 8 true positives and 2 false positives. What is precision in percent?',80,'Precision=8/(8+2)=80%.')],rubric:'Keep evaluation data separate and report an error measure that fits the intended use.'}
],
engineering:[
{prereq:'Describe a problem and compare measurable outcomes.',why:'Design criteria turn “better” into something testable.',depth:'A requirement specifies needed behavior; a constraint limits feasible solutions. Generate alternatives before selecting one. A prototype answers a question at low cost. Test one change at a time when identifying its effect, and record failures as evidence rather than hiding them.',advanced:'A design space can contain competing objectives such as cost, mass, reliability, and performance. A Pareto-optimal design cannot improve one objective without worsening another. Weighted scores encode stakeholder priorities and should be tested for sensitivity.',example:'Design A spans 20 cm for 8 units of cost; B spans 25 cm for 12. If the requirement is span≥20 and budget≤10, only A is feasible. Scoring an infeasible design highly does not make it acceptable.',mistake:'A neat appearance does not demonstrate that a prototype meets its measurable requirements.',model:'design',questions:[q('A bridge must reach 5 spaces. Your bridge reaches 4. How many more spaces are needed?',1,'5−4=1.'),q('A design costs 8 under a budget of 10. How much budget remains?',2,'10−8=2.'),q('Scores are 4 for cost and 8 for reliability. With equal weights 0.5, what is the total score?',6,'0.5×4+0.5×8=6; weights express priorities.')],rubric:'State two measurable criteria, compare alternatives, and record a test-driven revision.'},
{prereq:'Compare forces and distances from a pivot.',why:'Levers reveal how geometry changes mechanical advantage.',depth:'A perpendicular force creates torque equal to force times lever arm. Rotational balance requires clockwise and anticlockwise torques to cancel, along with translational balance for a stationary structure. A longer arm can trade distance moved for force required.',advanced:'Torque is the cross product r×F; its magnitude is rF sinθ. Static equilibrium requires both ΣF=0 and Στ=0. Choosing a convenient pivot eliminates unknown reaction torques but not the need to satisfy force balance.',example:'A 4 N force at 0.3 m gives 1.2 N·m. To balance it with 6 N on the other side, use a 0.2 m arm. Equal forces are not necessary when distances differ.',mistake:'The distance in torque is the perpendicular lever arm, not necessarily the length along the lever.',model:'torque',questions:[q('A force of 2 acts at distance 3 in a simple lever model. What is 2×3?',6,'Force times distance gives the turning measure.'),q('A 4 N force acts perpendicularly 0.3 m from a pivot. What is torque in N·m?',1.2,'4×0.3=1.2 N·m.'),q('To balance 1.2 N·m using a perpendicular 6 N force, what arm length in metres is needed?',0.2,'r=τ/F=1.2/6=0.2 m.')],rubric:'Label the pivot, perpendicular arms, and torque directions; verify both balance conditions.'},
{prereq:'Use voltage, current, and resistance with units.',why:'Circuit models predict component interactions before a physical build.',depth:'Series resistances add because the same current crosses each resistor and voltage drops add. Parallel branches share voltage and split current. Component tolerances and power ratings matter. Use simulation or low-voltage supervised equipment; mains electricity is outside this activity.',advanced:'Kirchhoff’s current law follows charge conservation; voltage-loop relationships assume an appropriate lumped-circuit model. For two parallel resistors, 1/R_eq=1/R₁+1/R₂. Nonlinear devices need a different constitutive model from a constant resistor.',example:'A 6 V source across two 100 Ω series resistors sees 200 Ω, giving 0.03 A. Each resistor drops 3 V and dissipates 0.09 W.',mistake:'Adding a parallel branch reduces equivalent resistance for positive resistors, while adding a series resistor increases it.',model:'series',questions:[q('Two resistors have values 2 and 3 in series. What is their total?',5,'Series values add: 2+3=5.'),q('A 6 V source sees 200 Ω. What current flows in amperes?',0.03,'I=6/200=0.03 A.'),q('Two equal 100 Ω resistors are in parallel. What is equivalent resistance in ohms?',50,'1/R=1/100+1/100=2/100, so R=50 Ω.')],rubric:'Draw the actual topology, calculate current and power, and state the model’s limits.'},
{prereq:'Distinguish measurement from action.',why:'Sensors and actuators connect computation to physical systems.',depth:'A sensor maps a physical quantity to an electrical or digital signal; calibration relates the reading to known references. Resolution is the smallest represented increment, while accuracy describes closeness to the true value. Actuators produce changes and may saturate at limits.',advanced:'A linear calibration y=ax+b can be estimated from reference points, but residuals test whether that model is adequate. Measurement uncertainty propagates into control decisions. Hysteresis or filtering can prevent noisy signals from repeatedly toggling outputs.',example:'A sensor reads 2 units at 0 cm and 12 units at 5 cm. Assuming a linear model, reading=2×distance+2, so a reading of 8 corresponds to 3 cm.',mistake:'Many displayed decimal places do not guarantee high accuracy.',model:'sensor',questions:[q('A rover’s eyes notice a wall and its wheels move. How many of those two parts are sensors?',1,'The sensing part notices; the wheels are driven by actuators.'),q('Reading=2×distance+2. What reading corresponds to distance 3?',8,'2×3+2=8.'),q('For reading=2×distance+2, what distance gives reading 12?',5,'Subtract 2 and divide by 2: (12−2)/2=5.')],rubric:'Identify input/output units, calibrate with references, and describe one noise-handling strategy.'},
{prereq:'Subtract a measurement from a target.',why:'Feedback lets systems correct deviations rather than follow a fixed plan blindly.',depth:'A reference is the desired value. Error is reference minus measurement. A proportional controller multiplies error by gain to choose an action, then measures again. Delay, noise, and saturation can change behavior substantially.',advanced:'For the ideal update yₖ₊₁=yₖ+K(r−yₖ), error follows eₖ₊₁=(1−K)eₖ. Stability requires |1−K|<1, so 0<K<2. For 1<K<2 errors alternate in sign while shrinking. This bound is specific to the stated plant model.',example:'With target 10, y₀=2, K=0.5, successive positions are 6,8,9. Errors are 4,2,1 after the updates. The controller approaches the target geometrically.',mistake:'A gain that works in a delay-free simulation may oscillate on a real delayed system.',model:'control',questions:[q('The flag is at 6 and the rover at 4. How many spaces remain?',2,'Error=6−4=2.'),q('Target 10, position 4, gain 0.5. What is the next position?',7,'Correction=0.5×6=3; next position=7.'),q('Starting error 8 with gain 0.5, what is the error after three ideal updates?',1,'8×(1−0.5)³=1.')],rubric:'Record error over time, compare gains, and state the plant assumptions before claiming stability.'},
{prereq:'Read a condition and identify a sensor or actuator.',why:'Automation must define safe responses to both normal and failed inputs.',depth:'A state machine lists states, transitions, and the conditions that trigger them. Each state should specify outputs. A fault state handles invalid or missing data. Test transitions at boundaries and make a recovery policy explicit rather than assuming errors never happen.',advanced:'Safety invariants express properties that must always hold, such as “the pump is off when the sensor is invalid.” Hysteresis avoids rapid toggling near a threshold. Watchdogs and fail-safe states respond to stalled execution or lost communication, subject to system-specific hazard analysis.',example:'A virtual pump starts below moisture 30 and stops above 50. At 40 it keeps its previous state, creating hysteresis. A missing measurement forces the pump off regardless of the previous state.',mistake:'Treating missing sensor data as a numerical zero may trigger an unsafe action.',model:'automation',questions:[q('A watering robot cannot read its sensor. Should it keep pumping? Enter 1 for yes, 0 for no.',0,'The specified safe response is to stop and report the fault.'),q('A pump starts below 30. At moisture 20, enter 1 for on or 0 for off.',1,'20 is below the start threshold.'),q('Start below 30, stop above 50. What is the width of the hysteresis band?',20,'The thresholds differ by 50−30=20.')],rubric:'Define normal and fault states, show every transition, and test invalid-input behavior.'}
],
logic:[
{prereq:'Recognize repeated groups and compare neighboring terms.',why:'Patterns help form hypotheses, but a hypothesis still needs justification.',depth:'A repeating sequence cycles through a finite block; an arithmetic sequence adds a fixed difference. A formula summarizes a proposed rule. Many rules can fit finitely many observations, so distinguish a chosen model from a logically forced conclusion.',advanced:'An arithmetic sequence has aₙ=a₁+(n−1)d. Differences help identify polynomial models, but interpolation does not establish the generating mechanism. A counterexample can refute a universal claim even when many examples support it.',example:'For 3,7,11,15, the constant difference is 4. Under the arithmetic model, the fifth term is 19 and the tenth is 3+9×4=39. That continuation depends on choosing the arithmetic model.',mistake:'A few matching terms do not prove that only one continuation is possible.',model:'sequence',questions:[q('Using “add 2,” what follows 2,4,6?',8,'Add 2 to 6.'),q('For 3,7,11,15 under an arithmetic rule, what is next?',19,'The common difference is 4.'),q('For a₁=3 and d=4, what is a₁₀?',39,'3+(10−1)×4=39.')],rubric:'State the rule, test all observed terms, and separate conjecture from proof.'},
{prereq:'Understand “all,” “some,” and “not.”',why:'Valid reasoning separates what follows from what merely sounds plausible.',depth:'A conditional “if P then Q” rules out P true with Q false. It does not assert the converse. Deductive validity depends on form; soundness also needs true premises. Induction generalizes evidence and can be useful without guaranteeing the conclusion.',advanced:'Modus ponens infers Q from P→Q and P; modus tollens infers ¬P from P→Q and ¬Q. Affirming the consequent is invalid. Truth tables evaluate propositional form but do not establish the truth of empirical premises.',example:'All squares are rectangles; shape A is a square; therefore A is a rectangle. But observing that B is a rectangle does not prove it is a square: a 2×3 rectangle is a counterexample.',mistake:'A true conclusion reached by invalid reasoning does not make the argument valid.',model:'logic',questions:[q('All shapes in a box are triangles. A shape comes from the box. How many sides does it have?',3,'The premise says every shape in that box has three sides.'),q('Does “all squares are rectangles” imply “all rectangles are squares”? Enter 1 for yes, 0 for no.',0,'A non-square rectangle is a counterexample.'),q('How many assignments of truth values to P and Q make P→Q false?',1,'Only P=true and Q=false violates the conditional.')],rubric:'Name premises and conclusion, test a counterexample, and separate validity from factual truth.'},
{prereq:'Follow a sequence and evaluate a yes/no question.',why:'Explicit decision paths make reasoning inspectable and repeatable.',depth:'Flowcharts use action boxes, decision diamonds, and arrows to show control flow. Label branches and ensure every possible input follows a defined path. Decompose a large decision into smaller tests with clear responsibilities.',advanced:'A control-flow graph exposes reachable states and paths. Tests can cover branches without covering every combination of paths. Invariants help reason about loops, and preconditions prevent invalid operations before a branch is evaluated.',example:'To choose the maximum of a and b, test a>b. The true branch returns a; the false branch returns b. Equality is still handled correctly because either equal value is a valid maximum.',mistake:'An unlabeled branch hides assumptions about what “yes” and “no” mean.',model:'flow',questions:[q('A path asks “is 7 bigger than 4?” Enter 1 for yes, 0 for no.',1,'7 is greater than 4, so follow yes.'),q('A max flowchart receives 4 and 9. What should it output?',9,'The comparison sends execution to the branch returning 9.'),q('Three independent yes/no decisions have how many possible combinations?',8,'Each decision doubles the combinations: 2³=8.')],rubric:'Label decisions, cover equality and invalid inputs, and trace at least two different paths.'},
{prereq:'Read a table and compare magnitudes.',why:'A chart should make comparisons accurate rather than merely dramatic.',depth:'Bars encode magnitude by length, so their baseline matters. Lines emphasize ordered change; scatter plots show paired observations. Label axes and units and explain missing values. Summary statistics condense data but can obscure spread and outliers.',advanced:'Visual encodings have different perceptual precision. Truncated baselines in bar charts distort relative lengths; transformations may be appropriate for other charts when disclosed. Aggregation can hide subgroup differences, so inspect the data-generating process.',example:'Values 2,4,6 have mean 4. Replacing 6 by 24 makes mean 10 while the median stays 4. A summary should match the question, and the raw data should remain inspectable.',mistake:'A chart with a convincing shape does not establish causation or representativeness.',model:'data',questions:[q('Three bars show 2,4,6. How tall is the tallest?',6,'Compare all three bar labels.'),q('What is the mean of 2,4,6?',4,'Total 12 divided by 3 is 4.'),q('For 2,4,24, what is mean minus median?',6,'Mean=10, median=4, difference=6.')],rubric:'Choose a justified chart, label scales and units, and discuss an outlier or aggregation effect.'},
{prereq:'Distinguish a sample from a whole group.',why:'Evidence quality matters more than the confidence of a conclusion.',depth:'A sampling frame determines who can be selected. Random sampling addresses some selection effects but not every measurement problem. Larger samples reduce random variability under assumptions; they do not automatically remove systematic bias. Association requires alternative explanations before causal interpretation.',advanced:'For an independent sample mean, standard error scales as σ/√n under suitable conditions. Confounding, selection, and measurement error affect inference differently. A randomized intervention can support causal inference when its design and assumptions are appropriate.',example:'A survey at a swimming pool finds many swimmers. Even 1,000 responses there may misrepresent a city’s preferences. A smaller but well-designed citywide sample can address the intended population more directly.',mistake:'Increasing the size of a biased sample does not necessarily make it representative.',model:'sampling',questions:[q('Pip asks only bike riders how they travel. Should Pip also ask walkers? Enter 1 for yes, 0 for no.',1,'Include people missing from the original sample.'),q('Three observations are 2,4,6. What is their mean?',4,'The sample mean is (2+4+6)/3=4.'),q('To halve standard error under the independent-sampling model, by what factor must sample size grow?',4,'Standard error scales as 1/√n, so quadrupling n halves it.')],rubric:'Define the population, identify who is missed, and separate bias from random variability.'},
{prereq:'Compare options against a stated goal.',why:'Decision models clarify trade-offs and the assumptions behind a recommendation.',depth:'A feasible option satisfies every hard constraint. An objective ranks feasible choices. Weighted scores combine criteria only after choosing meaningful scales and weights. Sensitivity analysis changes assumptions to see whether the decision is stable.',advanced:'A Pareto frontier contains options not dominated on every objective. Scalarization can miss some nonconvex trade-offs. Optimization of a proxy may fail the actual human goal; robustness and fairness can be constraints or additional objectives.',example:'Route A takes 10 minutes and costs 4 units; B takes 14 minutes and costs 2. With score=time+2×cost (lower is better), both score 18. Different weights can change the preferred route.',mistake:'A numerical score is not neutral when its criteria and weights encode value choices.',model:'optimization',questions:[q('One path takes 3 steps and another 5. How many steps does the shorter save?',2,'5−3=2.'),q('Score=time+2×cost. What is the score for time 10 and cost 4?',18,'10+2×4=18.'),q('A has time 10, cost 4; B has time 14, cost 2. At what cost weight do time+weight×cost scores tie?',2,'10+4w=14+2w gives w=2.')],rubric:'Separate constraints and preferences, compare feasible options, and test sensitivity to one weight.'}
]};
export const topicId=(age,subject,index,part='learn')=>`${age}:${subject}:topic:${index}:${part}`;
export function topicContent(subject,index,age){const g=guides[subject]?.[index],e=extensions[subject]?.[index];if(!g||!e)throw Error('Unknown topic');return {...e,subject,index,age,title:g[0],topic:subjects.find(s=>s.id===subject).topics[index],concept:g[1],worked:[g[2],e.example],project:age==='primary'?primaryProjects[subject][index]:g[3],rubric:age==='primary'?'Show what you tried. Draw or tell what changed. Explain one thing you noticed. You can ask a grown-up to write your words.':e.rubric,story:g[4]};}
